import{At as e,Et as t,ft as n,ht as r,lt as i,mt as a,n as o}from"./chunks/framework.CK3_e0nb.js";var s=JSON.parse(`{"title":"秋叶落下的声音","description":"秋风起时，落叶便成了一场盛大的告别。一片金黄的银杏叶脱离枝头，在空中打了几个旋儿，最终轻轻落在泥土上。 那声音极轻微，若非屏息凝神，几乎无法察觉。人们常悲秋，叹落叶飘零、草木枯槁，但大自然从不曾真正哀叹消亡。凋零并非终点，而是生命另一种形式的回归与馈赠，化作春泥更护花。树木褪去繁茂的枝叶，是为了熬过","frontmatter":{"id":"7ea8f9","title":"秋叶落下的声音","datetime":"2026-10-08 10:00:00","category":"散文","tags":["四季","感悟"]},"headers":[],"relativePath":"essays/7ea8f9.md","filePath":"essays/essay-08.md","lastUpdated":1792855556000}`),c={name:`essays/7ea8f9.md`};function l(o,s,c,l,u,d){let f=e(`PostMeta`);return t(),n(`div`,null,[s[0]||=i(`h1`,{id:`秋叶落下的声音`,tabindex:`-1`},[a(`秋叶落下的声音 `),i(`a`,{class:`header-anchor`,href:`#秋叶落下的声音`,"aria-label":`Permalink to “秋叶落下的声音”`},`​`)],-1),r(f),s[1]||=i(`p`,null,`秋风起时，落叶便成了一场盛大的告别。一片金黄的银杏叶脱离枝头，在空中打了几个旋儿，最终轻轻落在泥土上。`,-1),s[2]||=i(`p`,null,`那声音极轻微，若非屏息凝神，几乎无法察觉。人们常悲秋，叹落叶飘零、草木枯槁，但大自然从不曾真正哀叹消亡。凋零并非终点，而是生命另一种形式的回归与馈赠，化作春泥更护花。树木褪去繁茂的枝叶，是为了熬过凛冬的严寒；人在经历低谷与失去时，又何尝不是在积蓄重生的养分？学会接受生活中的失去与缺憾，才能像深秋的树木那样，站立在风中从容不迫，等待下一个明媚的暖春。`,-1)])}var u=o(c,[[`render`,l]]);export{s as __pageData,u as default};